  INSERT INTO public.diretrizes (numero, nome) VALUES (1, 'Fortalecer a atenção primária à saúde, vigilância em saúde e a assistência farmacêutica, como estratégias fundamentais para a promoção, prevenção, cuidado e monitoramento das condições de saúde da população, promovendo a ampliação do acesso, a qualificação da atenção e o alcance das metas dos indicadores nacionais da Atenção Primária em saúde (APS)') RETURNING id INTO diretriz_id;
  INSERT INTO public.objetivos (diretriz_id, numero, nome, descricao) VALUES (diretriz_id, 1, 'Objetivo 1.1 - Aumentar a resolutividade e a efetividade das ações da APS', 'Aumentar a resolutividade e a efetividade das ações da APS, por meio do monitoramento e melhoria contínua dos indicadores pactuados, com ênfase na prevenção de doenças crônicas, ampliação da cobertura de pré-natal adequado, rastreamento do câncer, e acompanhamento de condições prioritárias') RETURNING id INTO objetivo_id;
  INSERT INTO public.metas (objetivo_id, numero, descricao, indicador, criterios_avaliacao, meta_2026, meta_2027, meta_2028, meta_2029, meta_plano_2026_2029, meta_pas_2026, unidade_medida, responsavel) VALUES (objetivo_id, 1, 'Ampliar o acesso da população cadastrada aos atendimentos por demanda programada na Atenção Primária à Saúde, consolidando o vínculo e o acompanhamento longitudinal dos usuários pelas equipes de Saúde da Família, com base em planejamento territorial, qualificação do agendamento, ampliação de oferta de consultas e integração dos diversos pontos de atenção da Rede de Saúde', 'Mais acesso à Atenção Primária à Saúde. (Indicador C1 - Mais Acesso à Atenção Primária à Saúde (APS) - PT GM MS 3493/2024', 'Ótimo: >50% e <=70% Bom: >30% e <=50% Suficiente: >10% e <=30% Regular: <=10% ou >70%', '35%', '45%', '55%', '65%', '65%', '65%', 'Percentual', 'Atenção Primária') RETURNING id INTO meta_id;
  INSERT INTO public.acoes (meta_id, numero, descricao) VALUES (meta_id, 1, 'Revisar e organizar a agenda das equipes de Saúde da Família para equilibrar atendimentos de demanda espontânea e programada;');
  INSERT INTO public.acoes (meta_id, numero, descricao) VALUES (meta_id, 2, 'Ampliar a estratificação de risco da população cadastrada, priorizando o seguimento regular de grupos vulneráveis (crianças, gestantes, hipertensos, diabéticos etc.);');
  INSERT INTO public.acoes (meta_id, numero, descricao) VALUES (meta_id, 3, 'Acompanhar mensalmente o número e tipo de atendimentos realizados.');
  INSERT INTO public.metas (objetivo_id, numero, descricao, indicador, criterios_avaliacao, meta_2026, meta_2027, meta_2028, meta_2029, meta_plano_2026_2029, meta_pas_2026, unidade_medida, responsavel) VALUES (objetivo_id, 2, 'Promover a atuação multiprofissional e intersetorial voltada à vigilância do desenvolvimento, à orientação parental, à atualização do calendário vacinal e à detecção precoce de agravos e atrasos, consolidando a APS como espaço de cuidado contínuo e promotor de um início de vida saudável', 'Cuidado no desenvolvimento infantil na Atenção Primária à Saúde. (Indicador C2 - Cuidado no desenvolvimento infantil) - PT GM MS 3493/2024', 'Ótimo: >75% a 100% Bom: >50% <=75% Suficiente: >25% e <=50% Regular: 0 a 25%', '55%', '55%', '75%', '100%', '100%', '55%', 'Percentual', 'Atenção Primária') RETURNING id INTO meta_id;
  INSERT INTO public.acoes (meta_id, numero, descricao) VALUES (meta_id, 1, 'Realizar busca ativa semanal de recém-nascidos no território pelas equipes de Saúde da Família, com apoio dos Agentes Comunitários de Saúde (ACS);');
