  INSERT INTO public.acoes (meta_id, numero, descricao) VALUES (meta_id, 3, 'Identificar as dificuldades pontuadas pelos cidadãos, quanto ao acesso às ações e serviços de saúde;');
  INSERT INTO public.metas (objetivo_id, numero, descricao, indicador, criterios_avaliacao, meta_2026, meta_2027, meta_2028, meta_2029, meta_plano_2026_2029, meta_pas_2026, unidade_medida, responsavel) VALUES (objetivo_id, 4, 'Participar de todas as reuniões da CIR, e demais colegiados correlatos', 'Número participações da gestão em reuniões da CIR/COSEMS', '', '10', '10', '10', '10', '40', '1', 'Número', 'Gestão') RETURNING id INTO meta_id;
  INSERT INTO public.metas (objetivo_id, numero, descricao, indicador, criterios_avaliacao, meta_2026, meta_2027, meta_2028, meta_2029, meta_plano_2026_2029, meta_pas_2026, unidade_medida, responsavel) VALUES (objetivo_id, 4, 'Garantir as condições necessária para o funcionamento das atividades administrativas das da Secretaria Municipal de Saúde', 'Número de Secretaria Municipal de Saúde funcionando.', '', '1', '1', '1', '1', '1', '1', 'Número', 'Gestão') RETURNING id INTO meta_id;
  INSERT INTO public.acoes (meta_id, numero, descricao) VALUES (meta_id, 1, 'Avaliação do cumprimento de indicadores e metas pactuados, tendo em vista a concessão de incentivo financeiro anual para os profissionais d a sede.');
  INSERT INTO public.diretrizes (numero, nome) VALUES (8, 'Inovação, informação e tecnologia em saúde - Expandir o uso de sistemas interoperáveis e dados qualificados para decisão') RETURNING id INTO diretriz_id;
  INSERT INTO public.objetivos (diretriz_id, numero, nome, descricao) VALUES (diretriz_id, 1, 'Objetivo 8.1 - Promover a transformação digital na gestão e no cuidado em saúde', 'Promover a transformação digital na gestão e no cuidado em saúde, garantindo a ampliação do uso de sistemas interoperáveis, a qualificação e segurança das informações em saúde e o fortalecimento da análise de dados para apoiar decisões clínicas e gerenciais, aprimorando a qualidade e a integração da atenção oferecida à população') RETURNING id INTO objetivo_id;
  INSERT INTO public.metas (objetivo_id, numero, descricao, indicador, criterios_avaliacao, meta_2026, meta_2027, meta_2028, meta_2029, meta_plano_2026_2029, meta_pas_2026, unidade_medida, responsavel) VALUES (objetivo_id, 1, 'Expandir e qualificar o uso de sistemas eletrônicos de registro de informações em todas as unidades de saúde do município, assegurando a informatização dos processos assistenciais e gerenciais para fortalecer a continuidade do cuidado, a integração dos dados e a tomada de decisão em saúde', 'Percentual de unidades de saúde que utilizam sistemas eletrônicos de registro de informações. [(Número de unidades de saúde com sistemas eletrônicos de registro de informações) / (Total de unidades de saúde do município) x 100]', '', '90%', '90%', '100%', '100%', '100%', '100%', 'Percentual', 'Gestão') RETURNING id INTO meta_id;
  INSERT INTO public.metas (objetivo_id, numero, descricao, indicador, criterios_avaliacao, meta_2026, meta_2027, meta_2028, meta_2029, meta_plano_2026_2029, meta_pas_2026, unidade_medida, responsavel) VALUES (objetivo_id, 1, 'Expandir a infraestrutura tecnológica das unidades de saúde, assegurando a disponibilidade de computadores e dispositivos eletrônicos adequados ao uso de sistemas de informação e ao apoio das atividades assistenciais e administrativas, contribuindo para maior qualidade, agilidade e segurança no cuidado em saúde', 'Percentual de unidades de saúde equipadas com computadores e outros dispositivos eletrônicos. [(Número de unidades de saúde equipadas devidamente com computadores e outros dispositivos eletrônicos) / (Total de unidades de saúde do município) x 100]', '', '90%', '90%', '100%', '100%', '100%', '100%', 'Percentual', 'Gestão') RETURNING id INTO meta_id;
